// How much smaller is the domain of the NORMALISER than the domain of Gamma?
//
// Everything in this directory expands forms on the circle of radius rho, the circumradius of the
// Dirichlet domain of Gamma, and the term count is NT = T ln10 / (-ln rho).  But every model this
// project stores is of a quotient by an Atkin-Lehner subgroup W, and a W-invariant form is a form
// on the LARGER group Gamma_W generated by Gamma and the Atkin-Lehner elements of W.  Its
// Dirichlet domain is 1/#W of the area and therefore has a smaller circumradius -- and since NT
// goes as 1/(-ln rho) with rho close to 1, a modest reduction in rho is a large reduction in NT
// and a cubic one in the cost of the decomposition.
//
// This measures the gain without building anything: it reduces many points of the disc over
// Gamma_W (descending over the side pairing of Gamma, then over the Atkin-Lehner translates, until
// nothing decreases the modulus) and reports the largest modulus reached, which is rho for the
// larger group.  It is a lower estimate -- a sample can miss the outermost corner -- so the number
// to quote is the one with the margin, and the sampling is dense enough that it stops moving.
//
//   magma -b BASES:=10_9,85_1,35_1 PR:=80 NPT:=4000 TGT:=20 BOX:=3 rhostar.m < /dev/null
AttachSpec("/Users/assaferan/Documents/GitHub/ShimuraCurveALQuotients/worktrees/campaign/ShimuraQuotients.spec");
SetColumns(0);
load "/Users/assaferan/Documents/GitHub/ShimuraCurveALQuotients/worktrees/campaign/vvdata/weyl-campaign/voight-willis/vw3.m";
load "/Users/assaferan/Documents/GitHub/ShimuraCurveALQuotients/worktrees/campaign/vvdata/weyl-campaign/voight-willis/vwal.m";

PREC := StringToInteger(PR); NPT := StringToInteger(NPT);
TGT := StringToInteger(TGT); BOXSZ := StringToInteger(BOX);
CC := ComplexField(PREC); RR := RealField(PREC); R4 := RealField(4);
H := UpperHalfPlane();

// Descend over the side pairing of Gamma and over the Atkin-Lehner translates alternately: a
// point of the Gamma domain is carried into the smaller domain by one element of W, and
// re-reducing by Gamma after each Atkin-Lehner step is what makes the descent terminate there.
function ReduceOverW(Ws, Als, w, CC)
    cur := w;
    _, cur := ReduceByPairing(Ws, cur, CC);
    for it in [1..40] do
        best := Abs(cur); bw := cur; moved := false;
        for M in Als do
            nw := (M[1][1]*cur + M[1][2])/(M[2][1]*cur + M[2][2]);
            if Abs(nw) ge 1 then continue; end if;
            _, nw := ReduceByPairing(Ws, nw, CC);
            if Abs(nw) lt best - 1e-25 then best := Abs(nw); bw := nw; moved := true; end if;
        end for;
        if not moved then break; end if;
        cur := bw;
    end for;
    return cur;
end function;

printf "%-8o %-7o %-8o %-9o %-9o %-7o %-7o %o\n",
    "base", "vol", "#W*", "rho(Gam)", "rho(Gam*)", "NT", "NT*", "cost ratio";
for b in Split(BASES, ",") do
    xs := Split(b, "_");
    D := StringToInteger(xs[1]); N := StringToInteger(xs[2]); DN := D*N;
    A := QuaternionAlgebra(D); O := QuaternionOrder(A, N);
    G := FuchsianGroup(O);
    t0 := Cputime();
    _, DD, FD := RecentredDisc(G, H, PREC, 3);
    rho := Max([Abs(ComplexValue(v)) : v in FD]);
    p := ComplexValue(DiscToPlane(H, DD ! 0) : Precision := PREC);
    mrep := FuchsianMatrixRepresentation(A : Precision := PREC);
    Ws := SidePairingMatrices(G, DD, mrep, p, CC);
    Wstar := { Integers() | d : d in Divisors(DN) | GCD(d, DN div d) eq 1 };
    Als := [];
    for m in [ d : d in Wstar | d gt 1 ] do
        ok, x := ALElement(O, m, BOXSZ);
        if ok then Append(~Als, DiscMatrix(mrep, x, CC ! p, CC)); end if;
    end for;
    // points spread over the Gamma domain: the circle of radius rho and its interior
    rmax := RR ! 0;
    for i in [1..NPT] do
        r := (RR ! (0.05 + 0.95*((i*5) mod 23)/23)) * rho;
        w := CC ! (r * Exp(2*Pi(RR)*CC.1*i*(Sqrt(RR ! 5)-1)/2));
        v := Abs(ReduceOverW(Ws, Als, w, CC));
        if v gt rmax then rmax := v; end if;
    end for;
    rst := Min(RR ! 0.999, 1.02*rmax);
    NT := TermsFor(rho, TGT); NTs := TermsFor(rst, TGT);
    printf "%-8o %-7o %-8o %-9o %-9o %-7o %-7o %o   (%o s, %o Atkin-Lehner elements)\n",
        b, R4!ArithmeticVolume(G), #Wstar, R4!rho, R4!rst, NT, NTs,
        R4!((RR ! NT/NTs)^2.82), R4!Cputime(t0), #Als;
end for;
printf "RHOSTAR DONE\n";
quit;
